// Clean the agent output for Telegram HTML mode.
// Truncates BEFORE tag insertion so <b>/<code> can never straddle the cut,
// and closes any stray open tags as a safety net.
const raw = $input.first().json.output ?? $input.first().json.text ?? '';
let text = String(raw);
// Cap raw text first (leaves room for tag wrappers and HTML-entity expansion)
if (text.length > 3500) text = text.slice(0, 3496) + '...';
// Strip fenced code blocks (keep content)
text = text.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '');
// Strip markdown headings
text = text.replace(/^\s*#{1,6}\s+/gm, '');
// Escape HTML entities BEFORE inserting our own tags
text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Paired bold
text = text.replace(/\*\*([^\s*][^*\n]*?[^\s*])\*\*/g, '<b>$1</b>');
text = text.replace(/\*([^\s*][^*\n]*?[^\s*])\*/g, '<b>$1</b>');
// Paired inline code
text = text.replace(/`([^`\n]+)`/g, '<code>$1</code>');
// Bullet markers at line start
text = text.replace(/^\s*\*\s+/gm, '• ');
// Kill any stray unpaired asterisks / backticks
text = text.replace(/\*/g, '').replace(/`/g, '');
// Safety net: close any unbalanced open tags (defensive)
const openStack = [];
const tagRe = /<(\/?)(b|code|i|u|s|pre)>/gi;
let m;
while ((m = tagRe.exec(text)) !== null) {
  if (m[1] === '/') {
    const ix = openStack.lastIndexOf(m[2].toLowerCase());
    if (ix !== -1) openStack.splice(ix, 1);
  } else {
    openStack.push(m[2].toLowerCase());
  }
}
while (openStack.length) text += '</' + openStack.pop() + '>';
return [{ json: { text, chat_id: $('Telegram Trigger').first().json.message.chat.id } }];

